// The table entry of this fingerprint (features.h: fingerprint(view)), or -1: a binary search over the sorted fingerprints.
inline int find_known(std::uint64_t fp)
{
	int lo = 0, hi = NKNOWN - 1;
	while (lo <= hi)
	{
		const int mid = (lo + hi) / 2;
		if (KNOWN[mid].fp == fp)
			return mid;
		if (KNOWN[mid].fp < fp)
			lo = mid + 1;
		else
			hi = mid - 1;
	}
	return -1;
}

// Our team's index in a table entry: 0 when our spawn region holds team A's lowest spawn tile, else 1.
inline int known_team(const MapView& m, const KnownMap& e)
{
	for (const int t : m.spawn_tiles[0])
		if (t == e.spawn_a)
			return 0;
	return 1;
}

// The same for a champion (no MapView): one host call
inline int known_team_game(const KnownMap& e)
{
	const int W = cambc::map::width();
	for (const auto p : cambc::map::spawn_region(cambc::team::ally).positions())
		if (p.y * W + p.x == e.spawn_a)
			return 0;
	return 1;
}

// The step-7 next-target model's two best groups (255 none) for a body of type `type` (cambc::champion_type) that captured group g
// at game round `round` on a known map: zero fuel. nullptr when the table has no entry.
inline const std::uint8_t* known_dl_next(const KnownMap& e, int team, int round, int type, int g)
{
	if (!e.dl_next || team < 0 || team > 1 || type < 0 || type >= 13 || g < 0 || g >= e.ngroups)
		return nullptr;
	const int ph = round < DL_TABLE_SPLIT ? 0 : 1;
	return e.dl_next + 2 * (((static_cast<int>(team) * 2 + ph) * 13 + type) * e.ngroups + g);
}

